T.append(("custom-consolidators", "Custom calendar consolidator: USDJPY daily bars from 5 PM ET with EMA filter",
 [["usdjpy"], ["quotebarconsolidator"], ["calendarinfo"], ["exponentialmovingaverage", ".ema("], ["register_indicator"]], {
 ("individual", "precise"): "Trade USD/JPY using daily bars that run from 5pm New York time to 5pm the next day. Build a quote bar consolidator with a custom calendar function for that, attach a 10 period EMA to the consolidator, and warm it up by feeding 29000 minute quote bars from history into the consolidator. Whenever a consolidated bar finishes, once the EMA is ready and warm-up is done: if I'm not long and the close is above the EMA, go all in; if the close is below the EMA, sell everything. Sept 1 to Dec 31 2024.",
 ("individual", "over_specified"): "Trade USD/JPY using daily bars that run from 5pm New York time to 5pm the next day. Build a quote bar consolidator with a custom calendar function for that, attach a 10 period EMA to the consolidator, and warm it up by feeding 29000 minute quote bars from history into the consolidator. Whenever a consolidated bar finishes, once the EMA is ready and warm-up is done: if I'm not long and the close is above the EMA, go all in; if the close is below the EMA, sell everything. Sept 1 to Dec 31 2024. Also plot the close and the EMA on a chart named after the pair, hang the EMA off the forex object as an attribute, name the class CalendarConsolidatorExampleAlgorithm, and leave a comment showing the simpler one-day-with-offset consolidator alternative.",
 ("startup", "vague"): "USDJPY, forex-style daily bars anchored 17:00 ET via custom consolidator, long above EMA(10) else flat. Q4 2024. Fast.",
 ("startup", "over_specified"): "add_forex('USDJPY'); pair.ema = ExponentialMovingAverage(10). QuoteBarConsolidator(calendar_fn) where calendar_fn: start = dt at midnight, minus 7h if dt.hour < 17 else plus 17h, return CalendarInfo(start, timedelta(1)). consolidator.data_consolidated += handler; subscription_manager.add_consolidator(pair, consolidator); register_indicator(pair, pair.ema, consolidator); warm: for bar in history[QuoteBar](symbol, 29000, MINUTE): consolidator.update(bar). handler: return if not ema.is_ready or is_warming_up; plot(symbol.value, 'Close', close) and 'EMA'; not holdings.is_long and close > ema -> set_holdings(pair, 1); close < ema -> liquidate(). 2024-09-01 to 2024-12-31. snake_case, typed, comment the alternative timedelta(1), timedelta(hours=17) constructor.",
 ("institutional", "vague"): "The FX desk wants a trend filter on USDJPY for the September to December 2024 window, consistent with our internal implementation: daily bars aligned to the 5 PM New York session roll built with a custom consolidator, a short EMA registered to those bars, fully long above trend and flat below. Standard paper account.",
 ("institutional", "over_specified"): "Implement the desk's custom-calendar consolidator reference on USDJPY. Window: 2024-09-01 to 2024-12-31. Instrument: USDJPY forex at the default resolution. Consolidation: a QuoteBarConsolidator driven by a calendar function returning a one-day period starting at 17:00 Eastern (midnight of the date, minus 7 hours before 17:00 and plus 17 hours otherwise); attach the consolidated-bar handler, register the consolidator with the subscription manager, and register a 10-period EMA stored on the forex object to it. Warm-up: feed 29,000 minute quote bars from history through the consolidator. Rules in the handler, once the EMA is ready and warm-up is complete: not long and close above the EMA, allocate 100%; close below the EMA, liquidate. Compliance: plot close and EMA for audit, no action during warm-up, single long position with no leverage beyond 100% notional, snake_case API per our style guide, type annotations, comment the session anchoring.",
 ("reference", "ceiling"): "QuantConnect Python, snake_case. initialize: set_start_date(2024, 9, 1), set_end_date(2024, 12, 31), pair = add_forex('USDJPY'), pair.ema = ExponentialMovingAverage(10), consolidator = QuoteBarConsolidator(self._daily_forex_consolidation_period), consolidator.data_consolidated += self._consolidation_handler, subscription_manager.add_consolidator(pair, consolidator), register_indicator(pair, pair.ema, consolidator); for bar in history[QuoteBar](pair.symbol, 29000, Resolution.MINUTE): consolidator.update(bar). _daily_forex_consolidation_period(dt) -> CalendarInfo: start = dt.replace(hour=0, minute=0, second=0, microsecond=0); start -= timedelta(hours=7) if dt.hour < 17 else start += timedelta(hours=17); return CalendarInfo(start, timedelta(1)). _consolidation_handler(sender, bar): return if not pair.ema.is_ready or is_warming_up; plot(bar.symbol.value, 'Close', bar.close); plot(bar.symbol.value, 'EMA', pair.ema.current.value); if not pair.holdings.is_long and bar.close > ema: set_holdings(pair, 1); if bar.close < ema: liquidate().",
}))

