# --- end templates ---

here = Path(__file__).parent
train_dir = here / "train_templates"
test_folders = {p.name for p in (here / "templates").iterdir() if p.is_dir()}

rows = []
seen = set()
for folder, name, must, mine in T:
    assert folder not in seen, folder
    seen.add(folder)
    assert folder not in test_folders and folder not in EXCLUDED, folder
    assert (train_dir / folder / "main.py").exists(), folder
    existing = {(s, sp): p for (f, s, sp), p in EXISTING.items() if f == folder}
    overlap = set(existing) & set(mine)
    assert not overlap, (folder, overlap)
    cells = {**existing, **mine}
    missing = [c for c in GRID if c not in cells]
    extra = [c for c in cells if c not in GRID]
    assert not missing and not extra, (folder, missing, extra)
    for i, (segment, spec) in enumerate(GRID, 1):
        rows.append({
            "id": f"{folder}_v{i:02d}", "template_id": folder, "template": name,
            "reference_path": f"data/train_templates/{folder}/main.py",
            "version": i, "segment": segment, "specificity": spec,
            "persona": f"{segment} / {spec}",
            "prompt": cells[(segment, spec)],
            "must_contain": [] if spec == "vague" else must,
            "expects_orders": True,
            "author": "fiona" if (segment, spec) in existing else "aaditya",
        })

# Rows in EXISTING for templates not (yet) in T are kept verbatim at the end of the txt file.
leftover = [(f, s, sp, p) for (f, s, sp), p in EXISTING.items() if f not in seen]

with open(here / "train_prompts_src.txt", "w", encoding="utf-8") as f:
    f.write("# Training prompts for templates in data/train_templates/ (never the 10 eval templates).\n")
    f.write("# Format: folder | segment | specificity | prompt\n")
    f.write("# Generated by data/build_train_prompts.py: 10 prompts per template in grid order\n")
    f.write("# (3 segments x 3 specificity levels + ceiling). The template's main.py is the target answer.\n")
    for r in rows:
        assert "\n" not in r["prompt"] and " | " not in r["prompt"], r["id"]
        f.write(f"{r['template_id']} | {r['segment']} | {r['specificity']} | {r['prompt']}\n")
    for folder, s, sp, p in leftover:
        f.write(f"{folder} | {s} | {sp} | {p}\n")

with open(here / "train_prompts.jsonl", "w", encoding="utf-8") as f:
    for r in rows:
        f.write(json.dumps(r, ensure_ascii=False) + "\n")

print(f"templates: {len(T)}  rows: {len(rows)}  leftover existing rows: {len(leftover)}")
